// FUNCTIONS //

/**
* Returns the cumulative number of subsets of `{1,2,...,n}` whose elements sum to at most `k`, for each `k` from zero to `n(n+1)/2`.
*
* ## Notes
*
* -   For `n <= 11`, all counts are at most `2^11`, so dividing by `2^n` yields the exact null distribution of the signed rank statistic in double-precision floating-point arithmetic.
*
* @private
* @param {PositiveInteger} n - number of observations
* @returns {Array<number>} cumulative counts
*/
function cumulativeCounts( n ) {
	var counts;
	var M;
	var i;
	var k;

	M = n * ( n+1 ) / 2;
	counts = [ 1 ];
	for ( k = 1; k <= M; k++ ) {
		counts.push( 0 );
	}
	for ( i = 1; i <= n; i++ ) {
		for ( k = M; k >= i; k-- ) {
			counts[ k ] += counts[ k-i ];
		}
	}
	for ( k = 1; k <= M; k++ ) {
		counts[ k ] += counts[ k-1 ];
	}
	return counts;
}


