	var x;

	// Alternative: mu > 0.0
	x = greater.x;
	out = wilcoxon( x, {
		'alternative': 'greater'
	});

	// Tested against R:
	expected = greater.pValue;
	t.strictEqual( isAlmostSameValue( out.pValue, expected, 33 ), true, 'returns expected value' );

	expected = greater.statistic;
	t.strictEqual( isAlmostSameValue( out.statistic, expected, 0 ), true, 'returns expected value' );

	// Alternative: mu < 0.0
	x = less.x;
	out = wilcoxon( x, {
		'alternative': 'less'
	});

	// Tested against R:
