tape( 'the function returns an object with a `.print()` method for generating a formatted output of results of one-sample Wilcoxon signed rank test', function test( t ) {
	var table;
	var out;
	var x;

	x = [ 0, 1, 2, 3, 4 ];
	out = wilcoxon( x );
	table = out.print();
	t.strictEqual( typeof table, 'string', 'returns a pretty-printed table' );

	out = wilcoxon( x, {
		'alternative': 'less'
	});
	table = out.print();
	t.strictEqual( typeof table, 'string', 'returns a pretty-printed table' );

	out = wilcoxon( x, {
		'alternative': 'greater',
		'mu': 10
	});
	table = out.print();
	t.strictEqual( typeof table, 'string', 'returns a pretty-printed table' );
	t.end();
});

